<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Client\Application\Usecase\IssueInitialAccessToken;

use InvalidArgumentException;
use DateTimeImmutable;
use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\DcrInitialAccessTokenGateway;

/**
 * Issues a DCR initial access token (task 023): generates a 256-bit random token, stores it
 * through DcrInitialAccessTokenGateway (only its digest is kept; the gateway applies the tenant
 * admin access policies) and returns the plain value, which is never available again.
 */
final class IssueInitialAccessTokenUsecase
{
    public function __construct(
        private readonly DcrInitialAccessTokenGateway $gateway,
    ) {
    }

    public function issue(IssueInitialAccessTokenParams $params): IssueInitialAccessTokenResult
    {
        if ($params->maxUses < 1) {
            throw new InvalidArgumentException('maxUses must be at least 1');
        }
        if ($params->expiresAt <= new DateTimeImmutable()) {
            throw new InvalidArgumentException('expiresAt must be in the future');
        }
        $token = bin2hex(random_bytes(32));
        $uid = $this->gateway->issue(
            $token,
            $params->tenantUid,
            $params->description,
            $params->expiresAt,
            $params->maxUses,
            $params->allowedGrantTypes,
        );
        return new IssueInitialAccessTokenResult(
            uid: $uid,
            token: $token,
            expiresAt: $params->expiresAt,
            maxUses: $params->maxUses,
            allowedGrantTypes: $params->allowedGrantTypes,
        );
    }
}
